const body = $input.first().json.body || $input.first().json;
return [{ json: {
  request: body.request || body.transcript || body.message || '',
  userId: body.userId || body.user_id || 'test-user-123',
  diet: body.diet || null
} }];

const raw = $json.data ?? $json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
if (!text || !text.trim()) {
  throw new Error('Intent Agent returned an empty response — check its own execution log.');
}
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1 || end < start) {
  throw new Error('Intent Agent did not return any JSON object. Raw text: ' + text.slice(0, 800));
}
const cleaned = text.slice(start, end + 1);
try {
  return [{ json: JSON.parse(cleaned) }];
} catch (e) {
  throw new Error('Intent Agent returned malformed JSON: ' + e.message + ' | extracted: ' + cleaned.slice(0, 800));
}

const raw = $json.data ?? $json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
if (!text || !text.trim()) {
  return { json: { category: 'unknown', candidates: [], error: 'Quality Agent returned an empty response for this category' } };
}
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1 || end < start) {
  return { json: { category: 'unknown', candidates: [], error: 'Quality Agent did not return JSON: ' + text.slice(0, 300) } };
}
const cleaned = text.slice(start, end + 1);
try {
  return { json: JSON.parse(cleaned) };
} catch (e) {
  return { json: { category: 'unknown', candidates: [], error: 'Malformed JSON from Quality Agent: ' + e.message } };
}

const nutriRank = { A: 1, B: 0.75, C: 0.5, D: 0.25, E: 0 };
const novaRank = { 1: 1, 2: 0.67, 3: 0.33, 4: 0 };

const results = $('Aggregate Quality Results').item.json.results || [];
const items = $input.all().map(i => i.json);
const maybeArray = items[0];
const prefsRow = Array.isArray(maybeArray) ? maybeArray[0] : (maybeArray && maybeArray.user_id ? maybeArray : null);
const prefs = prefsRow || { price_sensitivity: 0.5, quality_weight: 0.5, sessions_observed: 0, preferred_brands: {}, typical_quantities: {} };
const typicalQuantities = prefs.typical_quantities || {};

function resolveQuantity(category, requestedQty) {
  // requestedQty === 1 is ambiguous (could be an explicit '1' or just the default) — when the user
  // has a learned typical quantity for this category, prefer that over the bare default.
  if (requestedQty && requestedQty !== 1) return requestedQty;
  const key = Object.keys(typicalQuantities).find(k => k.toLowerCase() === (category || '').toLowerCase());
  return key ? typicalQuantities[key] : (requestedQty || 1);
}

const scored = results.map(r => {
  if (r.error || !r.candidates || r.candidates.length === 0) {
    return { category: r.category, notes: r.notes, quantity: resolveQuantity(r.category, r.quantity), candidates: [], skippedReason: r.error || 'no candidates found' };
  }
  const eligible = r.candidates.filter(c => c.hasPrice && (!c.dietConflicts || c.dietConflicts.length === 0));
  if (eligible.length === 0) {
    return { category: r.category, notes: r.notes, quantity: resolveQuantity(r.category, r.quantity), candidates: [], skippedReason: 'no priced, diet-safe candidates found for this category' };
  }
  const notesLower = (r.notes || '').toLowerCase();
  const wantsProtein = notesLower.includes('protein');
  const wantsLowCal = notesLower.includes('calorie');

  const prices = eligible.map(c => c.price);
  const minPrice = Math.min(...prices);
  const maxPrice = Math.max(...prices);
  const proteinValues = eligible.map(c => c.proteinPer100g).filter(v => typeof v === 'number');
  const maxProtein = proteinValues.length ? Math.max(...proteinValues) : null;
  const calorieValues = eligible.map(c => c.caloriesPer100g).filter(v => typeof v === 'number');
  const maxCalories = calorieValues.length ? Math.max(...calorieValues) : null;
  const minCalories = calorieValues.length ? Math.min(...calorieValues) : null;

  const scoredCandidates = eligible.map(c => {
    const hasLabel = Boolean(c.ingredientsText && (c.nutriScore || c.novaGroup));
    const nutriScore = nutriRank[c.nutriScore] ?? 0.5;
    const novaScore = novaRank[c.novaGroup] ?? 0.5;
    const qualityScore = (nutriScore + novaScore) / 2;
    const priceScore = maxPrice > minPrice ? 1 - (c.price - minPrice) / (maxPrice - minPrice) : 1;
    const rawUtility = (prefs.quality_weight * qualityScore) + (prefs.price_sensitivity * priceScore);
    // unlabeled candidates are still shown, just ranked below labeled ones at equal price/quality odds
    let utility = hasLabel ? rawUtility : rawUtility * 0.6;
    // goal-based nudge: modest additive bonus so a stated goal shifts ranking without fully overriding price/quality
    if (wantsProtein && typeof c.proteinPer100g === 'number' && maxProtein > 0) {
      utility += 0.25 * (c.proteinPer100g / maxProtein);
    }
    if (wantsLowCal && typeof c.caloriesPer100g === 'number' && maxCalories > minCalories) {
      utility += 0.25 * (1 - (c.caloriesPer100g - minCalories) / (maxCalories - minCalories));
    }
    return { ...c, utility: Number(utility.toFixed(4)), dataFlag: hasLabel ? null : 'no nutrition label found for this product — shown anyway, ranked below labeled options' };
  }).sort((a, b) => b.utility - a.utility);
  return { category: r.category, notes: r.notes, quantity: resolveQuantity(r.category, r.quantity), candidates: scoredCandidates, skippedReason: null };
});

return [{ json: {
  results: scored,
  preferences: { priceSensitivity: prefs.price_sensitivity, qualityWeight: prefs.quality_weight, sessionsObserved: prefs.sessions_observed || 0, preferredBrands: prefs.preferred_brands || {} },
  budget: $('Parse Intent').item.json.budget,
  userId: $('Parse Request').item.json.userId
} }];

const raw = $json.data ?? $json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
if (!text || !text.trim()) {
  throw new Error('Suggestion Agent returned an empty response — check its own execution log.');
}
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1 || end < start) {
  throw new Error('Suggestion Agent did not return any JSON object. Raw text: ' + text.slice(0, 800));
}
const cleaned = text.slice(start, end + 1);
try {
  return [{ json: JSON.parse(cleaned) }];
} catch (e) {
  throw new Error('Suggestion Agent returned malformed JSON: ' + e.message + ' | extracted: ' + cleaned.slice(0, 800));
}
